<script lang="ts">import{checkFeature,expansionFeature}from'@fex-design/core';import type{TransferPanelApi}from'@fex-design/svelte/primitive/transfer';import DemoTree from'../tree/demo-tree.svelte';import type{Member}from'./data';let{api}:{api:TransferPanelApi<Member>}=$props();let treeData=$derived(Array.from(new Set(api.items.map(i=>i.department))).map(department=>({id:`department:${department}`,name:department,children:api.items.filter(i=>i.department===department)})))</script><DemoTree treeData={treeData as any} fieldNames={{key:'id',title:'name',disabled:'disabled'}} features={[expansionFeature({defaultExpandedKeys:treeData.map(i=>i.id)}),checkFeature()]} checkedKeys={api.checkedKeys} onCheckedKeysChange={api.setCheckedKeys} checkable/>
